-- Code generated by togo. PostgreSQL query fragment - safe to edit.
-- name: GetDomain :one
SELECT * FROM domains WHERE id = $1;

-- name: ListDomains :many
SELECT * FROM domains ORDER BY created_at DESC LIMIT $1 OFFSET $2;

-- name: CreateDomain :one
INSERT INTO domains (team_id, app_id, hostname, tls, verify_token, verified_at)
VALUES ($1, $2, $3, $4, $5, $6)
RETURNING *;

-- name: DeleteDomain :exec
DELETE FROM domains WHERE id = $1;

-- Hosbah tenant queries.
-- name: InsertDomain :one
INSERT INTO domains (team_id, app_id, hostname, tls, verify_token) VALUES ($1, $2, $3, $4, $5) RETURNING *;

-- name: ListDomainsOfApp :many
SELECT * FROM domains WHERE app_id = $1 AND team_id = $2 ORDER BY hostname;

-- name: ListDomainsOfTeam :many
-- MH-578 E8: every app hostname of the team, for the DNS zone manager's "Hosbah manages this" badge.
SELECT * FROM domains WHERE team_id = $1 ORDER BY hostname;

-- name: DomainOfApp :one
-- A domain of the app by id or by hostname.
SELECT * FROM domains
WHERE app_id = sqlc.arg('app_id')::text AND team_id = sqlc.arg('team_id')::text
  AND (id = sqlc.arg('ref')::text OR hostname = sqlc.arg('ref')::text);

-- name: DeleteDomainInTeam :execrows
DELETE FROM domains WHERE id = $1 AND team_id = $2;

-- name: MarkDomainVerified :exec
UPDATE domains SET verified_at = now(), updated_at = now() WHERE id = $1 AND team_id = $2;

-- name: TLSAllowed :one
-- System scope: Caddy's on-demand TLS ask. A certificate only for a verified auto-TLS domain.
SELECT ((SELECT count(*) FROM domains d WHERE d.hostname = $1 AND d.tls = 'auto' AND d.verified_at IS NOT NULL)
     + (SELECT count(*) FROM proxy_hosts p WHERE p.hostname = $1 AND p.tls = 'auto' AND p.enabled AND p.verified_at IS NOT NULL))::bigint AS n;

-- name: HostnameTaken :one
-- System scope: is this hostname routed anywhere in Hosbah (any team)?
SELECT ((SELECT count(*) FROM domains d WHERE d.hostname = $1) + (SELECT count(*) FROM proxy_hosts p WHERE p.hostname = $1))::bigint AS n;

-- name: SetDomainUpstream :exec
UPDATE domains SET upstream = sqlc.narg('upstream'), updated_at = now() WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: SetDomainTLS :exec
-- Team scope: flips a platform domain's tls mode, e.g. the apps-edge reconcile.
UPDATE domains SET tls = sqlc.arg('tls'), updated_at = now() WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: ListPlatformDomains :many
-- System scope: every app's platform hostname across every team, for the apps-edge reconcile.
SELECT * FROM domains WHERE verify_token = 'platform' ORDER BY hostname;

-- name: ListAdoptedAppsWithoutPlatformDomain :many
-- System scope: adopted git apps with no platform hostname (adopted before adoption gave one).
SELECT a.* FROM apps a
WHERE a.source = 'git' AND a.origin_kind IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM domains d WHERE d.app_id = a.id AND d.verify_token = 'platform')
ORDER BY a.created_at;
